head.script:
scwin.trigger1_onclick = function(e) {
    tabControl1.setStyle("height", "500px");
    //tabControl1.setWidth(200);
    //tabControl1.setHeight(200);
};
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step 1. 샘플파일 실행 후 개발자모드(F12)실행한다.
    //1. Execute the sample file and execute developer mode (F12).
    //Verify step 1. 샘플화면이 보여지고 개발자모드가 실행된다.
    //1. Sample screen is displayed and developer mode is executed.
    //Test step 2. console창에 'tabControl1.setWidth(200);'를 입력하고 EnterKey를 누른다.
    //2. In the console window, type 'tabControl1.setWidth (200);' and press EnterKey.
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('tabControl1').setWidth(200)");
    WebSquare.wUnit.addCommand("pause", "200");
    //Verify step 2. tabControl1의 넓이가 200으로 적용된다.
    //2. The width of tabControl1 is set to 200.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#tabControl1').css('width')", "200px");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 3. console창에 'tabControl1.setHeight(200);'를 입력하고 EnterKey를 누른다.
    //3. Type 'tabControl1.setHeight (200);' in the console window and press EnterKey.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('tabControl1').setHeight(200)");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify step 3. tabControl1의 높이가 200으로 적용된다.
    //3. The height of tabControl1 is set to 200.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#tabControl1').css('height')", "200px");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function 
    //Created by: Quan.Nguyen
    //Created date: 27-Feb-2018
    //end
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
